from pathlib import Path
import re

p=Path('index.html')
s=p.read_text()

# 1) Replace the separate quickbar/fake preview styling with a collapsible home card and real-page swipe layer.
pat=r"\.quickbar\{.*?@media\(prefers-reduced-motion:reduce\)\{\.screen-swipe-backdrop,\.screen-swipe-preview-inner,\.shell\{transition:none!important\}\}"
new_css=""".home-priority{position:sticky;top:calc(env(safe-area-inset-top) + 6px);z-index:24;transition:padding .18s ease,border-radius .18s ease,box-shadow .18s ease,background .18s ease;margin-bottom:16px;transform:translateZ(0)}.home-priority-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.home-priority-settings{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:38px;padding:7px 10px;border:1px solid var(--line);border-radius:11px;background:var(--card2);color:var(--text);font:inherit;font-size:11px;font-weight:800;cursor:pointer}.home-priority-row{display:block}.home-priority-info{min-width:0}.home-priority-location{margin:0 0 12px;color:var(--muted);line-height:1.35}.home-priority-action{width:100%;margin-top:10px}.home-priority-extra{margin-top:0}.home-priority.compact{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center;gap:7px;margin-left:-4px;margin-right:-4px;padding:8px;border-radius:15px;background:var(--bg);background:color-mix(in srgb,var(--bg) 90%,transparent);box-shadow:0 8px 24px rgba(0,0,0,.2);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}.home-priority.compact .home-priority-head{display:contents}.home-priority.compact .home-priority-head>.kicker{display:none}.home-priority.compact .home-priority-row{display:contents}.home-priority.compact .home-priority-info{grid-column:1;grid-row:1;overflow:hidden}.home-priority.compact .home-odometer{margin:0;font-size:18px;line-height:1.05}.home-priority.compact .home-priority-location{margin:2px 0 0;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.home-priority.compact .home-priority-action{grid-column:2;grid-row:1;width:auto;min-height:40px;margin:0;padding:8px 10px;border-radius:11px;font-size:11px;white-space:nowrap}.home-priority.compact .home-priority-settings{grid-column:3;grid-row:1;width:42px;min-width:42px;min-height:40px;padding:6px;font-size:17px}.home-priority.compact .home-priority-settings span{display:none}.home-priority.compact .home-priority-extra{display:none}.home-priority.compact .active-route{margin:0;font-size:13px;line-height:1.15}.home-priority.compact .active-meta{margin-top:3px;font-size:10px}.home-priority.compact .active-meta .status{display:none}.home-priority.compact .active-meta>span:last-child{display:block;color:var(--muted);white-space:nowrap}.screen-swipe-layer{position:fixed;inset:0;z-index:45;overflow:hidden;pointer-events:none;background:transparent}.screen-swipe-layer>.shell{position:absolute;left:0;right:0;margin-left:auto;margin-right:auto;will-change:transform;box-shadow:0 0 24px rgba(0,0,0,.24)}.screen-transitioning .screen-swipe-edge-cue{opacity:0}.screen-swipe-edge-cue{position:fixed;top:46%;z-index:8;width:8px;height:44px;background:color-mix(in srgb,var(--accent) 38%,transparent);opacity:.34;pointer-events:none}.screen-swipe-edge-cue.right{right:0;border-radius:10px 0 0 10px}.screen-swipe-edge-cue.left{left:0;border-radius:0 10px 10px 0}.editor-view .screen-swipe-edge-cue{display:none}@media(max-width:430px){.home-priority.compact{grid-template-columns:minmax(0,1fr) auto auto;gap:5px}.home-priority.compact .home-priority-action{padding-left:8px;padding-right:8px}.home-priority-settings span{display:none}.home-priority-settings{width:40px;padding-left:6px;padding-right:6px;font-size:16px}}@media(prefers-reduced-motion:reduce){.home-priority,.screen-swipe-layer>.shell{transition:none!important}}"""
s,n=re.subn(pat,new_css,s,count=1,flags=re.S)
if n!=1: raise SystemExit(f'quickbar css replacement count {n}')

# 2) Remove the fake backdrop and separate quickbar; restore a simple page header/back control.
old_body='''<div id="screenSwipeBackdrop" class="screen-swipe-backdrop" aria-hidden="true"></div>\n<div id="screenSwipeEdgeCue" class="screen-swipe-edge-cue" aria-hidden="true"></div>\n<div class="shell" id="screenShell">\n<header class="top">\n<div><div id="today" class="eyebrow"></div><h1>Kilometerregistratie</h1></div>\n</header>\n<div id="quickBar" class="quickbar" aria-label="Snelle acties">\n<div id="quickStatus" class="quick-status"></div>\n<button id="quickPrimary" class="quick-primary" type="button" data-action="quick-primary"></button>\n<button id="topAction" class="quick-settings" type="button" data-action="settings" aria-label="Instellingen"><span class="quick-settings-icon">⚙︎</span><span class="quick-settings-label">Instellingen</span></button>\n</div>\n<main id="app"></main>'''
new_body='''<div id="screenSwipeEdgeCue" class="screen-swipe-edge-cue right" aria-hidden="true"></div>\n<div class="shell" id="screenShell">\n<header class="top">\n<div><div id="today" class="eyebrow"></div><h1>Kilometerregistratie</h1></div>\n<button id="topAction" class="iconbtn" type="button" data-action="home" aria-label="Terug naar ritten" hidden>←</button>\n</header>\n<main id="app"></main>'''
if old_body not in s: raise SystemExit('body quickbar marker not found')
s=s.replace(old_body,new_body,1)

# 3) Swipe tuning: larger, more forgiving back-swipe area on Settings.
old_const="const KEY='kmreg-v4-data',GEOCODE_CACHE_KEY='kmreg-geocode-cache-v1',GEOCODER_DEFAULT_BASE='https://nominatim.openstreetmap.org',SCREEN_EDGE_SWIPE_ZONE=64,SCREEN_EDGE_SWIPE_DISTANCE=88,SCREEN_SWIPE_VELOCITY=.52;"
new_const="const KEY='kmreg-v4-data',GEOCODE_CACHE_KEY='kmreg-geocode-cache-v1',GEOCODER_DEFAULT_BASE='https://nominatim.openstreetmap.org',SCREEN_EDGE_SWIPE_ZONE=72,SCREEN_BACK_SWIPE_RATIO=.45,SCREEN_EDGE_SWIPE_DISTANCE=88,SCREEN_SWIPE_VELOCITY=.5;"
if old_const not in s: raise SystemExit('swipe const marker not found')
s=s.replace(old_const,new_const,1)

old_refs="const app=document.getElementById('app'),modal=document.getElementById('modal'),modalPanel=document.getElementById('modalPanel'),toastEl=document.getElementById('toast'),topAction=document.getElementById('topAction'),quickStatus=document.getElementById('quickStatus'),quickPrimary=document.getElementById('quickPrimary'),screenShell=document.getElementById('screenShell'),screenSwipeBackdrop=document.getElementById('screenSwipeBackdrop'),screenSwipeEdgeCue=document.getElementById('screenSwipeEdgeCue'),printReportEl=document.getElementById('printReport');"
new_refs="const app=document.getElementById('app'),modal=document.getElementById('modal'),modalPanel=document.getElementById('modalPanel'),toastEl=document.getElementById('toast'),topAction=document.getElementById('topAction'),screenShell=document.getElementById('screenShell'),screenSwipeEdgeCue=document.getElementById('screenSwipeEdgeCue'),printReportEl=document.getElementById('printReport');"
if old_refs not in s: raise SystemExit('dom refs marker not found')
s=s.replace(old_refs,new_refs,1)

old_version="document.getElementById('today').textContent=new Intl.DateTimeFormat('nl-NL',{weekday:'long',day:'numeric',month:'long'}).format(new Date())+' · 0.28.20';"
new_version="document.getElementById('today').textContent=new Intl.DateTimeFormat('nl-NL',{weekday:'long',day:'numeric',month:'long'}).format(new Date())+' · 0.28.21';"
if old_version not in s: raise SystemExit('version marker not found')
s=s.replace(old_version,new_version,1)

# 4) Replace the separate quickbar logic. The home hero itself now collapses and stays.
old_logic="""function quickBarLocation(){const active=data.activeTrip,last=data.lastEndpoint||inferLast();return active?.origin||last?.location||null}
function quickBarStand(){const active=data.activeTrip,last=data.lastEndpoint||inferLast(),fallback=num(data.settings.initialOdometer);return active?.startOdometer??last?.odometer??fallback}
function renderQuickBar(){const active=data.activeTrip,stand=quickBarStand(),loc=quickBarLocation(),inSettings=view==='settings';quickStatus.innerHTML=`<span>${active?'Startstand':'Kilometerstand'}</span><strong>${stand!=null?odo(stand)+' km':'—'}</strong><small>${loc?esc(labelLoc(loc)):'Nog geen locatie'}</small>`;quickPrimary.dataset.action='quick-primary';quickPrimary.innerHTML=active?'<strong>Aankomst</strong><small>rit afronden</small>':'<strong>Vertrek</strong><small>registreren</small>';quickPrimary.setAttribute('aria-label',active?'Rit afronden':'Vertrek registreren');topAction.dataset.action=inSettings?'home':'settings';topAction.innerHTML=inSettings?'<span class=\"quick-settings-icon\">←</span><span class=\"quick-settings-label\">Ritten</span>':'<span class=\"quick-settings-icon\">⚙︎</span><span class=\"quick-settings-label\">Instellingen</span>';topAction.setAttribute('aria-label',inSettings?'Terug naar ritten':'Instellingen');screenSwipeEdgeCue.className='screen-swipe-edge-cue '+(inSettings?'left':'right')}
async function runQuickPrimary(){if(view!=='ride'){view='ride';window.scrollTo({top:0,behavior:'instant'});render()}if(data.activeTrip){if(arrivalDraft){document.getElementById('arrivalInlinePanel')?.scrollIntoView({behavior:'smooth',block:'start'});return}await openArrival();return}if(startDraft){document.getElementById('startInlinePanel')?.scrollIntoView({behavior:'smooth',block:'start'});return}await openStart()}
function render(){const editor=view==='trip-edit'||view==='location-edit';document.body.classList.toggle('editor-view',editor);document.body.classList.toggle('has-active-trip',view==='ride'&&!!data.activeTrip);if(view==='trip-edit'){renderTripEditPage();return}if(view==='location-edit'){renderLocationEditPage();return}renderQuickBar();if(view==='settings')renderSettings();else{view='ride';renderHome()}}
"""
new_logic="""let homePriorityRaf=0;
function updateHomePriorityCompact(){homePriorityRaf=0;const card=document.getElementById('homePriority');if(!card||view!=='ride')return;card.classList.toggle('compact',window.scrollY>58)}
function scheduleHomePriorityCompact(){if(homePriorityRaf)return;homePriorityRaf=requestAnimationFrame(updateHomePriorityCompact)}
function render(){const editor=view==='trip-edit'||view==='location-edit';document.body.classList.toggle('editor-view',editor);document.body.classList.toggle('has-active-trip',view==='ride'&&!!data.activeTrip);if(view==='trip-edit'){renderTripEditPage();return}if(view==='location-edit'){renderLocationEditPage();return}if(view==='settings'){topAction.hidden=false;topAction.dataset.action='home';topAction.textContent='←';topAction.setAttribute('aria-label','Terug naar ritten');screenSwipeEdgeCue.className='screen-swipe-edge-cue left';renderSettings()}else{view='ride';topAction.hidden=true;screenSwipeEdgeCue.className='screen-swipe-edge-cue right';renderHome();requestAnimationFrame(updateHomePriorityCompact)}}
"""
if old_logic not in s: raise SystemExit('quickbar logic block not found')
s=s.replace(old_logic,new_logic,1)

old_click="if(a==='settings'){view='settings';window.scrollTo({top:0,behavior:'instant'});render()}else if(a==='home'){view='ride';window.scrollTo({top:0,behavior:'instant'});render()}else if(a==='quick-primary')await runQuickPrimary();else if(a==='editor-back')leaveEditor();"
new_click="if(a==='settings'){view='settings';window.scrollTo({top:0,behavior:'instant'});render()}else if(a==='home'){view='ride';window.scrollTo({top:0,behavior:'instant'});render()}else if(a==='editor-back')leaveEditor();"
if old_click not in s: raise SystemExit('click nav block not found')
s=s.replace(old_click,new_click,1)

# 5) Make the actual existing home information the sticky/collapsing element.
old_home="""function renderHome(){const a=data.activeTrip,trips=periodTrips(),t=totals(trips),points=periodEvents(),last=data.lastEndpoint||inferLast(),activePoints=a?data.events.filter(x=>x.tripId===a.id):[];app.innerHTML=`
<section class=\"hero ${a?(arrivalDraft?'active-hero arrival-preparing':'active-hero'):startDraft?'start-preparing':''}\"><div class=\"kicker\">${a?'Actieve rit':'Huidige stand'}</div>${a?`<div class=\"active-route\"><strong>${esc(labelLoc(a.origin)||'Onbekend')}</strong><span>↓</span><strong>${esc(labelLoc(a.expectedDestination)||'Bestemming onbekend')}</strong></div><div class=\"active-meta\"><span class=\"status ${categoryClass(a.category||'business')}\"><span class=\"dot\"></span>${categoryLabel(a.category||'business')} · gestart ${time(a.departureTime)}</span><span>Startstand ${odo(a.startOdometer)} km</span></div>${activeRouteInsight(a)}${arrivalDraft?'<button class=\"btn secondary full arrival-main\" data-action=\"cancel-arrival\">Annuleer afronden</button>':'<button class=\"btn full arrival-main\" data-action=\"arrive\">Aankomst</button>'}<div class=\"ride-tools\">${a.expectedDestination&&(data.settings.navigationMode||'system')!=='off'?'<button class=\"ride-tool\" data-action=\"navigate-active\">Navigatie</button>':''}${a.expectedDestination&&rideSharePreference(a.expectedDestination)!=='never'?'<button class=\"ride-tool\" data-action=\"share-active\">Deel rit</button>':''}<button class=\"ride-tool\" data-action=\"tank\">Tanken</button><button class=\"ride-tool\" data-action=\"detour\">Omrijpunt</button></div>${activePoints.length?`<div class=\"hint active-points\">${activePoints.length} tussenpunt${activePoints.length===1?'':'en'} vastgelegd</div>`:''}`:`<h2 class=\"home-odometer\">${last?odo(last.odometer)+' km':'Nog geen beginstand'}</h2><p>${last?.location?'Laatste bestemming: '+esc(labelLoc(last.location)):'Vul bij Instellingen je auto en beginstand in.'}</p>${startDraft?'<button class=\"btn secondary full\" data-action=\"cancel-start\">Annuleer vertrek</button>':'<button class=\"btn full\" data-action=\"start\">Vertrek registreren</button>'}`}</section>
${backupReminderHtml()}
${homePeriodOrStartPanel(trips,t)}
<div class=\"section\"><div class=\"section-title\"><h2>Ritten</h2><span class=\"muted\">${trips.length}</span></div>${tripList(trips)}</div>
${points.length?`<div class=\"section\"><div class=\"section-title\"><h2>Onderweg geregistreerd</h2><span class=\"muted\">${points.length}</span></div>${routePointList(points)}</div>`:''}`}"""
new_home="""function renderHome(){const a=data.activeTrip,trips=periodTrips(),t=totals(trips),points=periodEvents(),last=data.lastEndpoint||inferLast(),activePoints=a?data.events.filter(x=>x.tripId===a.id):[];const settingsButton='<button type=\"button\" class=\"home-priority-settings\" data-action=\"settings\" aria-label=\"Instellingen\">⚙︎ <span>Instellingen</span></button>';app.innerHTML=`
<section id=\"homePriority\" class=\"hero home-priority ${a?(arrivalDraft?'active-hero arrival-preparing':'active-hero'):startDraft?'start-preparing':''}\"><div class=\"home-priority-head\"><div class=\"kicker\">${a?'Actieve rit':'Huidige stand'}</div>${settingsButton}</div>${a?`<div class=\"home-priority-row\"><div class=\"home-priority-info\"><div class=\"active-route\"><strong>${esc(labelLoc(a.origin)||'Onbekend')}</strong><span>↓</span><strong>${esc(labelLoc(a.expectedDestination)||'Bestemming onbekend')}</strong></div><div class=\"active-meta\"><span class=\"status ${categoryClass(a.category||'business')}\"><span class=\"dot\"></span>${categoryLabel(a.category||'business')} · gestart ${time(a.departureTime)}</span><span>Startstand ${odo(a.startOdometer)} km</span></div></div>${arrivalDraft?'<button class=\"btn secondary home-priority-action arrival-main\" data-action=\"cancel-arrival\">Annuleer afronden</button>':'<button class=\"btn home-priority-action arrival-main\" data-action=\"arrive\">Aankomst</button>'}</div><div class=\"home-priority-extra\">${activeRouteInsight(a)}<div class=\"ride-tools\">${a.expectedDestination&&(data.settings.navigationMode||'system')!=='off'?'<button class=\"ride-tool\" data-action=\"navigate-active\">Navigatie</button>':''}${a.expectedDestination&&rideSharePreference(a.expectedDestination)!=='never'?'<button class=\"ride-tool\" data-action=\"share-active\">Deel rit</button>':''}<button class=\"ride-tool\" data-action=\"tank\">Tanken</button><button class=\"ride-tool\" data-action=\"detour\">Omrijpunt</button></div>${activePoints.length?`<div class=\"hint active-points\">${activePoints.length} tussenpunt${activePoints.length===1?'':'en'} vastgelegd</div>`:''}</div>`:`<div class=\"home-priority-row\"><div class=\"home-priority-info\"><h2 class=\"home-odometer\">${last?odo(last.odometer)+' km':'Nog geen beginstand'}</h2><p class=\"home-priority-location\">${last?.location?'Laatste bestemming: '+esc(labelLoc(last.location)):'Vul bij Instellingen je auto en beginstand in.'}</p></div>${startDraft?'<button class=\"btn secondary home-priority-action\" data-action=\"cancel-start\">Annuleer vertrek</button>':'<button class=\"btn home-priority-action\" data-action=\"start\">Vertrek registreren</button>'}</div>`}</section>
${backupReminderHtml()}
${homePeriodOrStartPanel(trips,t)}
<div class=\"section\"><div class=\"section-title\"><h2>Ritten</h2><span class=\"muted\">${trips.length}</span></div>${tripList(trips)}</div>
${points.length?`<div class=\"section\"><div class=\"section-title\"><h2>Onderweg geregistreerd</h2><span class=\"muted\">${points.length}</span></div>${routePointList(points)}</div>`:''}`}"""
if old_home not in s: raise SystemExit('renderHome block not found')
s=s.replace(old_home,new_home,1)

# 6) Replace fake target preview with the actual rendered target page under a snapshot of the current page.
pat_swipe=r"function screenSwipePreviewHtml\(targetView\).*?function screenSwipeCancel\(\)\{.*?\}\n\nfunction tripSwipeStart"
new_swipe="""function syncSwipeCloneControls(source,clone){const a=source.querySelectorAll('input,select,textarea'),b=clone.querySelectorAll('input,select,textarea');a.forEach((el,i)=>{const c=b[i];if(!c)return;if('value'in c)c.value=el.value;if('checked'in c)c.checked=el.checked})}
function beginScreenSwipeVisual(g){if(g.visualStarted||!['ride','settings'].includes(g.sourceView))return;const layer=document.createElement('div'),clone=screenShell.cloneNode(true);syncSwipeCloneControls(screenShell,clone);clone.removeAttribute('id');clone.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));clone.classList.add('screen-swipe-snapshot');clone.style.top=`-${g.sourceScrollY}px`;clone.style.transition='none';clone.style.transform='translate3d(0,0,0)';layer.className='screen-swipe-layer';layer.setAttribute('aria-hidden','true');layer.appendChild(clone);document.body.appendChild(layer);g.layer=layer;g.snapshot=clone;g.visualStarted=true;document.body.classList.add('screen-transitioning');view=g.targetView;window.scrollTo({top:0,behavior:'instant'});render()}
function cleanupScreenSwipeVisual(g){g?.layer?.remove();document.body.classList.remove('screen-transitioning')}
function settleScreenSwipe(g,complete){if(!g)return;if(!g.visualStarted){if(complete&&g.sourceView==='trip-edit'||complete&&g.sourceView==='location-edit')leaveEditor();return}const width=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0),to=complete?(g.direction==='left'?-width:width):0;g.snapshot.style.transition='transform .2s cubic-bezier(.22,.8,.28,1)';g.snapshot.style.transform=`translate3d(${to}px,0,0)`;setTimeout(()=>{if(!complete){view=g.sourceView;render();window.scrollTo({top:g.sourceScrollY,behavior:'instant'})}else{view=g.targetView;window.scrollTo({top:0,behavior:'instant'})}cleanupScreenSwipeVisual(g)},205)}
function screenSwipeStart(e){if(e.button!=null&&e.button!==0)return;if(!modal.hidden)return;const width=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0),x=e.clientX,target=e.target instanceof Element?e.target:null,sourceView=view;let direction=null,targetView=null;if(sourceView==='ride'&&x>=width-SCREEN_EDGE_SWIPE_ZONE){direction='left';targetView='settings'}else if(sourceView==='settings'&&x<=Math.max(SCREEN_EDGE_SWIPE_ZONE,width*SCREEN_BACK_SWIPE_RATIO)&&!target?.closest('.swipe-row')){direction='right';targetView='ride'}else if((sourceView==='trip-edit'||sourceView==='location-edit')&&x<=SCREEN_EDGE_SWIPE_ZONE){direction='right';targetView=editorReturnView==='settings'?'settings':'ride'}if(!direction)return;if(target?.closest('input,select,textarea,[contenteditable=\"true\"]'))return;closeTripSwipes();screenSwipe={pointerId:e.pointerId,startX:x,startY:e.clientY,dx:0,dy:0,direction,horizontal:false,cancelled:false,sourceView,targetView,sourceScrollY:window.scrollY,startTime:performance.now(),lastX:x,lastMoveTime:performance.now(),velocityX:0,visualStarted:false};try{screenShell.setPointerCapture?.(e.pointerId)}catch(_){}}
function screenSwipeMove(e){const g=screenSwipe;if(!g||g.pointerId!==e.pointerId||g.cancelled)return;const dx=e.clientX-g.startX,dy=e.clientY-g.startY;g.dx=dx;g.dy=dy;if(!g.horizontal){if(Math.abs(dy)>12&&Math.abs(dy)>Math.abs(dx)){g.cancelled=true;return}if(Math.abs(dx)>9&&Math.abs(dx)>Math.abs(dy)*1.08){g.horizontal=true;if(['ride','settings'].includes(g.sourceView))beginScreenSwipeVisual(g)}else return}const correct=g.direction==='left'?dx<0:dx>0;if(!correct){if(Math.abs(dx)>20){g.cancelled=true;screenSwipe=null;settleScreenSwipe(g,false)}return}const now=performance.now(),dt=Math.max(1,now-g.lastMoveTime);g.velocityX=(e.clientX-g.lastX)/dt;g.lastX=e.clientX;g.lastMoveTime=now;if(g.visualStarted){const width=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0),limited=g.direction==='left'?Math.max(-width,Math.min(0,dx)):Math.min(width,Math.max(0,dx));g.snapshot.style.transition='none';g.snapshot.style.transform=`translate3d(${limited}px,0,0)`}if(e.cancelable)e.preventDefault()}
function screenSwipeEnd(e){const g=screenSwipe;if(!g||g.pointerId!==e.pointerId)return;screenSwipe=null;if(g.cancelled||!g.horizontal){if(g.visualStarted)settleScreenSwipe(g,false);return}const width=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0),distance=Math.min(150,Math.max(SCREEN_EDGE_SWIPE_DISTANCE,width*.24)),speed=g.direction==='left'?-g.velocityX:g.velocityX,correctDistance=g.direction==='left'?-g.dx:g.dx,complete=correctDistance>=distance||(correctDistance>=28&&speed>=SCREEN_SWIPE_VELOCITY);if((g.sourceView==='trip-edit'||g.sourceView==='location-edit')){if(complete)leaveEditor();return}settleScreenSwipe(g,complete)}
function screenSwipeCancel(){const g=screenSwipe;screenSwipe=null;if(g?.visualStarted)settleScreenSwipe(g,false)}

function tripSwipeStart"""
s,n=re.subn(pat_swipe,new_swipe,s,count=1,flags=re.S)
if n!=1: raise SystemExit(f'swipe block replacement count {n}')

# 7) Keep collapse state in sync while scrolling/resizing.
anchor="document.addEventListener('pointercancel',screenSwipeCancel);"
if anchor not in s: raise SystemExit('pointercancel anchor missing')
s=s.replace(anchor,anchor+"\nwindow.addEventListener('scroll',scheduleHomePriorityCompact,{passive:true});\nwindow.addEventListener('resize',scheduleHomePriorityCompact,{passive:true});",1)

# 8) Cache/version only. No data schema or ID changes.
sw=Path('service-worker.js')
w=sw.read_text()
if "kmreg-shell-0.28.20" not in w: raise SystemExit('service worker version not found')
w=w.replace('kmreg-shell-0.28.20','kmreg-shell-0.28.21',1)
sw.write_text(w)

# Guards.
for bad in ['quickStatus','quickPrimary','screenSwipeBackdrop','function screenSwipePreviewHtml']:
    if bad in s: raise SystemExit('old UI marker still present: '+bad)
for needed in ['id="homePriority"','home-priority-settings','function beginScreenSwipeVisual','SCREEN_BACK_SWIPE_RATIO=.45',"const ID_ALPHABET='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';"]:
    if needed not in s: raise SystemExit('missing marker: '+needed)
if 'migrateCoreIds' in s: raise SystemExit('unexpected ID migration code')
p.write_text(s)
